document.addEventListener("click",function(t){const e=t.target.closest(".js-clickable-card");if(!e)return;if(t.target.closest("a, button, input, textarea, select, label"))return;const n=e.dataset.href;n&&(window.location.href=n)}),document.addEventListener("keydown",function(t){const e=t.target.closest(".js-clickable-card");if(!e)return;if("Enter"!==t.key&&" "!==t.key)return;t.preventDefault();const n=e.dataset.href;n&&(window.location.href=n)});